GLOSSARY_DATA = [{'category': 'options', 'categoryLabel': 'Options basics', 'terms': [{'term': 'Call Option', 'th': 'Call Option', 'desc': 'The right, without obligation, to buy the underlying asset at the strike price before or at expiration, depending on the contract.', 'example': 'A $200 call has $30 of intrinsic value when the stock is $230; profit also depends on premium paid.'}, {'term': 'Put Option', 'th': 'Put Option', 'desc': 'The right, without obligation, to sell the underlying asset at the strike price before or at expiration, depending on the contract.', 'example': 'A $200 put has $30 of intrinsic value when the stock is $170; profit also depends on premium paid.'}, {'term': 'Strike Price', 'th': 'Strike Price', 'desc': 'The price at which the option holder can buy or sell the underlying asset. It is distinct from the break-even price.', 'example': 'A call with a $290 strike and $10 premium breaks even at $300 at expiration, before fees.'}, {'term': 'Premium', 'th': 'Premium', 'desc': 'The price paid to buy an option. A buyer can lose the entire premium.', 'example': 'A $0.50 premium per share typically costs $50 for a standard 100-share contract.'}, {'term': 'Expiry / Expiration', 'th': 'Expiry / Expiration', 'desc': 'The date when an option expires. Out-of-the-money options expire without intrinsic value.', 'example': 'The stock price at expiration determines the intrinsic value of an expiring option.'}, {'term': 'ATM (At The Money)', 'th': 'ATM (At The Money)', 'desc': 'An option whose strike price is close to the current underlying price.'}, {'term': 'OTM (Out of The Money)', 'th': 'OTM (Out of The Money)', 'desc': 'An option with no intrinsic value: a call above the underlying price or a put below it.', 'example': 'A $290 call when the stock is $215 is out of the money.'}, {'term': 'ITM (In The Money)', 'th': 'ITM (In The Money)', 'desc': 'An option with intrinsic value: a call below the underlying price or a put above it. Being in the money does not guarantee a net profit.'}]}, {'category': 'metrics', 'categoryLabel': 'Option metrics', 'terms': [{'term': 'IV (Implied Volatility)', 'th': 'IV (Implied Volatility)', 'desc': 'Volatility implied by option prices. Higher implied volatility generally increases option premiums.', 'example': 'An IV of 120% implies greater annualized price uncertainty than 40%.'}, {'term': 'IV Crush', 'th': 'IV Crush', 'desc': 'A sharp drop in implied volatility, often after earnings or another anticipated event. It can reduce option value even when the stock moves favorably.', 'example': 'A call may lose value after earnings despite a rising stock price.'}, {'term': 'Delta', 'th': 'Delta', 'desc': 'The approximate change in option price for a $1 change in the underlying. Call delta is generally positive; put delta is negative.', 'example': 'A delta of 0.5 suggests roughly $0.50 of option price change for a $1 underlying move.'}, {'term': 'Theta', 'th': 'Theta', 'desc': 'The sensitivity of option value to the passage of time, with other inputs unchanged. Long options generally experience time decay.', 'example': 'Theta of -0.02 implies about $0.02 per share of daily decay under the model.'}, {'term': 'Gamma', 'th': 'Gamma', 'desc': 'The approximate change in delta for a $1 change in the underlying price.'}, {'term': 'Vega', 'th': 'Vega', 'desc': 'The sensitivity of option value to a one percentage point change in implied volatility.'}, {'term': 'Probability of Profit (PoP)', 'th': 'Probability of Profit (PoP)', 'desc': 'A model-based estimate of the chance that a trade finishes profitable. Premium, fees, assumptions and the chosen strategy matter. A strike probability is not the same as profit probability.'}, {'term': 'Expected Value (EV)', 'th': 'Expected Value (EV)', 'desc': 'The probability-weighted average outcome across possible gains and losses. Results depend on the assumed probabilities and payouts.', 'example': 'If a trade has a 60% chance to gain $50 and a 40% chance to lose $100, its expected value is -$10.'}]}]
